question.solution:
from collections import deque

def bfs_shortest(graph, start):
    if not graph or start not in graph:
        return {}
    dist = {start: 0}
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

chain = {0: [1], 1: [0, 2], 2: [1, 3], 3: [2]}
print(bfs_shortest(chain, 0))
print(bfs_shortest(chain, 3))
print(bfs_shortest({0: [1], 1: [0], 2: [3], 3: [2]}, 0))
print(bfs_shortest({}, 0))
print(bfs_shortest(chain, 9))

checks:
_g = {0: [1], 1: [0], 2: [3], 3: [2], 4: []}
_r = bfs_shortest(_g, 0)
assert 4 not in _r and 2 not in _r, '不可达的顶点不能出现在结果里，实际 %r' % (_r,)

_g = {0: [1, 2], 1: [0], 2: [0, 3], 3: [2]}
_copy = {_k: list(_v) for _k, _v in _g.items()}
bfs_shortest(_g, 0)
assert _g == _copy, '题面要求不要修改 graph，实际 %r' % (_g,)

_n = 500
_path = {}
for _i in range(_n):
    _nbrs = []
    if _i > 0:
        _nbrs.append(_i - 1)
    if _i < _n - 1:
        _nbrs.append(_i + 1)
    _path[_i] = _nbrs
_r = bfs_shortest(_path, 0)
assert len(_r) == _n and _r[_n - 1] == _n - 1, '500 个顶点的链应从 0 一直量到 499（距离 499），实际 %r' % (_r.get(_n - 1),)
